package local.skyfamily;
import android.os.Build;import android.content.Intent;import android.graphics.*;import android.view.*;import android.widget.*;import android.text.*;import org.xmlpull.v1.XmlPullParser;import java.io.*;import java.util.*;import java.util.regex.*;import java.text.SimpleDateFormat;
public class FamilyActivity extends ModernActivity {
 String day(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
 @Override void tile(String title,String subtitle,String mark,int color,Runnable action){if(title.equals("Daily word")){title="Word games";subtitle="Crossword, Word Trail and daily guess";}super.tile(title,subtitle,mark,color,action);}
 @Override void pick(boolean media){Intent i=new Intent(Build.VERSION.SDK_INT>=19?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_GET_CONTENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(media?"image/*":"*/*");if(media&&Build.VERSION.SDK_INT>=19){i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","video/*"});}try{startActivityForResult(Intent.createChooser(i,"Choose a file"),20);}catch(Exception e){toast("Install a file picker or reader first");}}
 @Override void puzzle(){page("Word games");text("Offline puzzles / progress saved on this device");button("Daily mini crossword",()->crossword());button("Word Trail / connect the letters",()->trail());button("Daily five-letter guess",()->super.puzzle());}
 void crossword(){page("Daily mini crossword");boolean alternate=(day().hashCode()&1)==0;String[] grid=alternate?new String[]{"###C###","###A###","##STOP#","####W##","##OIL##","##N####","##E####"}:new String[]{"###B###","###A###","##STAR#","####R##","##CAT##","##A####","##R####"};String[] clues=alternate?new String[]{"Across 2: Opposite of go (4)","Across 4: Liquid used to lubricate an engine (3)","Down 1: A pet that meows (3)","Down 3: A bird known for hooting (3)","Down 4: The first counting number (3)"}:new String[]{"Across 2: A bright object in the night sky (4)","Across 4: A pet that meows (3)","Down 1: A flying mammal (3)","Down 3: Creative work such as painting (3)","Down 4: A road vehicle with four wheels (3)"};text("Fill the numbered grid. Two rotating starter boards, selected by date.");EditText[][] cells=new EditText[7][7];String key="cross."+day()+".";int size=Math.max(28,Math.min(52,(getResources().getConfiguration().screenWidthDp-180)/7));for(int r=0;r<7;r++){LinearLayout row=new LinearLayout(this);body.addView(row);for(int c=0;c<7;c++){FrameLayout box=new FrameLayout(this);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(size),dp(size));bp.setMargins(dp(1),dp(1),dp(1),dp(1));row.addView(box,bp);if(grid[r].charAt(c)=='#'){box.setBackgroundColor(bg);continue;}EditText cell=new EditText(this);cells[r][c]=cell;cell.setSingleLine(true);cell.setTextColor(fg);cell.setTextSize(19);cell.setGravity(Gravity.CENTER);cell.setPadding(0,dp(8),0,0);cell.setBackground(shape(surface,edge,5));cell.setInputType(4097);cell.setFilters(new InputFilter[]{new InputFilter.AllCaps(),new InputFilter.LengthFilter(1)});String store=key+r+"."+c;cell.setText(get(store));box.addView(cell,new FrameLayout.LayoutParams(-1,-1));int number=r==0&&c==3?1:r==2&&c==2?2:r==2&&c==4?3:r==4&&c==2?4:0;if(number>0){TextView n=new TextView(this);n.setText(String.valueOf(number));n.setTextColor(accent);n.setTextSize(10);n.setPadding(dp(3),0,0,0);box.addView(n,new FrameLayout.LayoutParams(dp(16),dp(16)));}cell.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){save(store,s.toString());cell.setTextColor(fg);}public void afterTextChanged(Editable e){}});}}for(String clue:clues)text(clue);button("Check answers",()->{boolean won=true;for(int r=0;r<7;r++)for(int c=0;c<7;c++)if(cells[r][c]!=null){boolean correct=cells[r][c].getText().toString().equals(String.valueOf(grid[r].charAt(c)));cells[r][c].setTextColor(correct?accent:0xffff8797);if(!correct)won=false;}toast(won?"Crossword complete!":"Green letters are correct. Keep going.");});button("Reveal one letter",()->{for(int r=0;r<7;r++)for(int c=0;c<7;c++)if(cells[r][c]!=null&&!cells[r][c].getText().toString().equals(String.valueOf(grid[r].charAt(c)))){cells[r][c].setText(String.valueOf(grid[r].charAt(c)));return;}toast("Already complete");});}
 void trail(){page("Word Trail");String[][] levels={{"STONE","ONE","SON","TON","TONE","NOTE","STONE","NOTES","ONSET"},{"HEART","HEAR","HARE","HATE","HEAT","RATE","TEAR","HEART","EARTH"},{"TRAIN","RAIN","RANT","TARN","TIN","RAT","ART","TAN","TRAIN"},{"LIGHT","HIT","LIT","LIGHT"}};String[] level=levels[(day().hashCode()&0x7fffffff)%levels.length];Set<String> found=new HashSet<>();String key="trail."+day();for(String s:get(key).split(";"))if(!s.isEmpty())found.add(s);text("Swipe through letters without reusing a tile. Find the listed words. Four rotating starter levels; not a commercial Word Snack clone.");TextView targets=new TextView(this);targets.setTextSize(22);targets.setTextColor(fg);targets.setLineSpacing(dp(6),1);body.addView(targets);Runnable refresh=()->{StringBuilder s=new StringBuilder();for(int i=1;i<level.length;i++)s.append(found.contains(level[i])?level[i]:level[i].replaceAll(".","_ " )).append("\n");targets.setText(s);StringBuilder saved=new StringBuilder();for(String word:found)saved.append(word).append(';');save(key,saved.toString());};TextView current=new TextView(this);current.setTextColor(accent);current.setTextSize(25);body.addView(current);WordWheel wheel=new WordWheel(level[0],current,word->{boolean valid=false;for(int i=1;i<level.length;i++)if(level[i].equals(word))valid=true;if(!valid){toast("Not one of this puzzle's words");return;}if(!found.add(word)){toast("Already found");return;}refresh.run();toast(found.size()==level.length-1?"All words found!":"Found "+word);});body.addView(wheel,new LinearLayout.LayoutParams(-1,dp(310)));button("Shuffle letters",()->{Collections.shuffle(wheel.letters);wheel.selected.clear();wheel.invalidate();});EditText typed=input("Or type a word","");button("Submit typed word",()->{wheel.finish.accept(typed.getText().toString().trim().toUpperCase(Locale.US));typed.setText("");});button("Reveal one word",()->{for(int i=1;i<level.length;i++)if(!found.contains(level[i])){found.add(level[i]);refresh.run();return;}});refresh.run();}
 interface WordAction{void accept(String word);}
 class WordWheel extends View{ArrayList<Character> letters=new ArrayList<>();ArrayList<Integer> selected=new ArrayList<>();Paint pen=new Paint(3);TextView label;WordAction finish;WordWheel(String word,TextView l,WordAction f){super(FamilyActivity.this);for(char c:word.toCharArray())letters.add(c);Collections.shuffle(letters);label=l;finish=f;setContentDescription("Swipe letter wheel. A typed-word alternative is provided below.");}float cx(int i){return getWidth()/2f+(float)Math.cos(i*2*Math.PI/letters.size()-Math.PI/2)*Math.min(getWidth(),getHeight())*.33f;}float cy(int i){return getHeight()/2f+(float)Math.sin(i*2*Math.PI/letters.size()-Math.PI/2)*Math.min(getWidth(),getHeight())*.33f;}protected void onDraw(Canvas c){pen.setColor(accent);pen.setStrokeWidth(dp(6));for(int i=1;i<selected.size();i++)c.drawLine(cx(selected.get(i-1)),cy(selected.get(i-1)),cx(selected.get(i)),cy(selected.get(i)),pen);for(int i=0;i<letters.size();i++){pen.setColor(selected.contains(i)?accent:surface);c.drawCircle(cx(i),cy(i),dp(28),pen);pen.setColor(selected.contains(i)?bg:fg);pen.setTextSize(dp(25));pen.setTypeface(Typeface.DEFAULT_BOLD);pen.setTextAlign(Paint.Align.CENTER);c.drawText(String.valueOf(letters.get(i)),cx(i),cy(i)+dp(9),pen);}}public boolean onTouchEvent(MotionEvent e){if(e.getAction()==0){selected.clear();getParent().requestDisallowInterceptTouchEvent(true);}if(e.getAction()==0||e.getAction()==2){for(int i=0;i<letters.size();i++)if(Math.hypot(e.getX()-cx(i),e.getY()-cy(i))<dp(32)){if(selected.size()>1&&selected.get(selected.size()-2)==i)selected.remove(selected.size()-1);else if(!selected.contains(i))selected.add(i);break;}StringBuilder word=new StringBuilder();for(int i:selected)word.append(letters.get(i));label.setText(word);invalidate();}if(e.getAction()==1){String word=label.getText().toString();if(!selected.isEmpty())finish.accept(word);selected.clear();label.setText("");invalidate();getParent().requestDisallowInterceptTouchEvent(false);}if(e.getAction()==3){selected.clear();invalidate();getParent().requestDisallowInterceptTouchEvent(false);}return true;}}
 @Override void feed(String source,String url){page(source+" / headlines");text("Loading in-app news...");int stamp=revision;work(()->{byte[] bytes=request(url,"GET",null,"",4000000);XmlPullParser p=android.util.Xml.newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);p.setInput(new ByteArrayInputStream(bytes),null);ArrayList<HashMap<String,String>> rows=new ArrayList<>();HashMap<String,String> item=null;String field="";for(int e=p.getEventType();e!=XmlPullParser.END_DOCUMENT;e=p.next()){if(e==XmlPullParser.START_TAG){String n=p.getName();if(n.equals("item")||n.equals("entry")){item=new HashMap<>();}else if(item!=null){field=n;if(n.equals("link")){String href=p.getAttributeValue(null,"href");if(href!=null)item.put("link",href);}if(n.equals("thumbnail")||n.equals("content")||n.equals("enclosure")){String image=p.getAttributeValue(null,"url"),type=p.getAttributeValue(null,"type");if(image!=null&&(n.equals("thumbnail")||type!=null&&type.startsWith("image/")))item.put("image",image);}}}else if((e==XmlPullParser.TEXT||e==XmlPullParser.CDSECT)&&item!=null){item.put(field,item.containsKey(field)?item.get(field)+p.getText():p.getText());}else if(e==XmlPullParser.END_TAG){if((p.getName().equals("item")||p.getName().equals("entry"))&&item!=null){rows.add(item);item=null;if(rows.size()==30)break;}field="";}}ui.post(()->{if(stamp!=revision)return;body.removeAllViews();if(rows.isEmpty())text("This source returned no readable articles.");for(HashMap<String,String> row:rows){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(16),dp(16),dp(16));card.setBackground(press(surface));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(14);body.addView(card,cp);if(row.containsKey("image")){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(image,new LinearLayout.LayoutParams(-1,dp(170)));picture(image,row.get("image"),"");}TextView title=new TextView(this);title.setText(clean(row.get("title")));title.setTextColor(fg);title.setTextSize(23);card.addView(title);TextView meta=new TextView(this);meta.setText(source+" / "+clean(row.containsKey("pubDate")?row.get("pubDate"):row.get("published")));meta.setTextColor(accent);meta.setTextSize(13);card.addView(meta);TextView desc=new TextView(this);desc.setText(summary(row));desc.setTextColor(muted);desc.setMaxLines(3);card.addView(desc);card.setOnClickListener(v->article(source,row));}});});}
 String summary(HashMap<String,String> row){return clean(row.containsKey("description")?row.get("description"):row.containsKey("summary")?row.get("summary"):row.get("content"));}
 void article(String source,HashMap<String,String> row){page("Reading / "+source);text(clean(row.get("title")));text(source+" / "+clean(row.containsKey("pubDate")?row.get("pubDate"):row.get("published"))+" / "+clean(row.get("creator")));if(row.containsKey("image")){ImageView hero=new ImageView(this);hero.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(hero,new LinearLayout.LayoutParams(-1,dp(240)));picture(hero,row.get("image"),"");}TextView reading=new TextView(this);reading.setText(summary(row));reading.setTextColor(fg);reading.setTextSize(21);reading.setLineSpacing(dp(7),1.1f);reading.setTextIsSelectable(true);body.addView(reading);String link=row.get("link");button("Load available full article text in app",()->{if(link==null||!link.startsWith("https://")){toast("No supported HTTPS article URL");return;}int stamp=revision;work(()->{String html=new String(request(link,"GET",null,"",2000000),"UTF-8");Matcher article=Pattern.compile("(?is)<article\\b[^>]*>(.*?)</article>").matcher(html);if(!article.find())throw new IOException("Publisher supplies no extractable article. Feed summary remains available.");String content=article.group(1).replaceAll("(?is)<(script|style|nav|footer|aside)\\b[^>]*>.*?</\\1>","");Matcher paragraphs=Pattern.compile("(?is)<(?:p|h[1-6])\\b[^>]*>(.*?)</(?:p|h[1-6])>").matcher(content);StringBuilder result=new StringBuilder();while(paragraphs.find()){String line=clean(paragraphs.group(1));if(!line.isEmpty())result.append(line).append("\n\n");if(result.length()>80000)break;}if(result.length()<100)throw new IOException("Full text unavailable; publisher may require its own player, subscription or script.");String extracted=result.toString();ui.post(()->{if(stamp==revision)reading.setText(extracted);});});});button("Save article summary for offline reading",()->{String key="saved.article."+(link==null?row.get("title"):link);save(key,clean(row.get("title"))+"\n"+source+"\n\n"+summary(row));toast("Summary saved");});button("Open original publisher (optional)",()->{if(link==null||!link.startsWith("https://")){toast("No HTTPS source link");return;}try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(link)));}catch(Exception e){toast("No browser installed");}});text("Feed content and extracts remain credited to the publisher. Extractor does not bypass paywalls or guarantee complete article text.");}
 @Override void news(){super.news();button("Saved article summaries",()->{page("Saved reading");int count=0;for(Map.Entry<String,?> entry:prefs.getAll().entrySet())if(entry.getKey().startsWith("saved.article.")){String saved=String.valueOf(entry.getValue());button(saved.split("\n")[0],()->{page("Saved summary");text(saved);});count++;}if(count==0)text("No saved summaries yet. Open a story and save it.");});}
}
